package dev.jackteng.encore;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.jackteng.encore.admission.*;
import dev.jackteng.encore.catalog.*;
import dev.jackteng.encore.catalog.Models.*;
import dev.jackteng.encore.common.ApiErrors.Problem;
import dev.jackteng.encore.customer.CustomerService;
import dev.jackteng.encore.customer.CustomerService.Principal;
import dev.jackteng.encore.inventory.*;
import dev.jackteng.encore.inventory.RedisTicketLedger.*;
import dev.jackteng.encore.inventory.StockHoldService.Intent;
import dev.jackteng.encore.orders.*;
import dev.jackteng.encore.orders.OrderModels.*;
import dev.jackteng.encore.orders.PurchaseModels.Purchase;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.mock-payments.enabled=true","ticket.expiry.enabled=false","ticket.stock-recovery.enabled=false"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockRecoveryIntegrationTest {
 @Autowired StockRecoveryStore recovery;@Autowired StockRecoveryWorker worker;@Autowired StockHoldService holds;@Autowired StockSettlementService settlement;@Autowired StockProjectionService projections;@Autowired PurchaseService purchases;@Autowired OrderService orders;@Autowired CustomerService customers;@Autowired CatalogService catalog;
 @Autowired JdbcTemplate db;@Autowired StringRedisTemplate redis;@Autowired ObjectMapper json;@Autowired AdmissionSettings settings;@Autowired AdmissionService admission;@Autowired PlatformTransactionManager transactions;
 RedisTicketLedger ledger;Set<String> keys=new HashSet<>();String manager="recovery-"+UUID.randomUUID();
 record Fixture(Principal owner,UUID ticket,Place body,Intent intent) {}
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));ledger=RedisTicketLedger.epochs(redis,json,settings.namespace());db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"unused synthetic hash","MANAGER");}
 @AfterEach void cleanup(){redis.delete(keys);keys.clear();}
 Principal customer(){var c=customers.register("sp-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());return customers.authenticate(c.token()).orElseThrow();}
 Fixture fixture(){return fixture(7200);}
 Fixture fixture(int seconds){var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"bridge-"+UUID.randomUUID(),"合成演出","不售票","隔離"));var now=OffsetDateTime.now();var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成",now.plusDays(2),now.minusHours(1),now.plusSeconds(seconds)));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般",1200,4,4));catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);ready(t.id());var p=customer();var b=new Place(UUID.randomUUID(),t.id(),1,1,1200);var i=holds.prepare(p,b);assertEquals("HELD",holds.apply(i.id()).state());return new Fixture(p,t.id(),b,i);}
 void ready(UUID t){var c=projections.begin(t,UUID.randomUUID(),projections.inspect(t).sourceRevision());keys.add(ledger.key(t,c.generation()));assertEquals("READY",projections.complete(c.requestId()).state());}
 Purchase accept(Fixture f){return purchases.acceptHold(f.owner(),f.intent().id());}
 UUID event(Purchase p){return db.queryForObject("SELECT id FROM purchase_outbox WHERE purchase_id=?",UUID.class,p.id());}
 Purchase reserve(Fixture f){var p=accept(f);assertTrue(purchases.process(event(p)));return purchases.detail(f.owner(),p.id());}
 Claim claim(Fixture f){var i=f.intent();return new Claim(i.generation(),i.id(),i.owner(),i.quantity(),i.deadlineAt().toInstant().toEpochMilli(),db.queryForObject("SELECT claim_fingerprint FROM stock_hold_intent WHERE id=?",String.class,i.id()));}
 String decision(Fixture f){return db.queryForObject("SELECT target FROM stock_hold_decision WHERE intent_id=?",String.class,f.intent().id());}
 int held(Fixture f){return db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,f.ticket());}
 void problem(String code,Runnable op){assertEquals(code,assertThrows(Problem.class,op::run).code);}
 void active(Fixture f){problem("ACTIVE_STOCK_INTENTS",()->projections.begin(f.ticket(),UUID.randomUUID(),projections.inspect(f.ticket()).sourceRevision()));}


 void drain(){for(int n=0;n<1000;n++){var c=recovery.claim(30);if(c.isEmpty())return;worker.run(c.get());}fail("Recovery backlog unbounded in isolated fixture");}
 StockRecoveryStore.Claim claim(Fixture f,String kind){return claim(f,kind,30);}
 StockRecoveryStore.Claim claim(Fixture f,String kind,int leaseSeconds){for(int n=0;n<1000;n++){var c=recovery.claim(leaseSeconds);assertTrue(c.isPresent(),"Expected due durable work");if(c.get().intentId().equals(f.intent().id())&&c.get().kind().equals(kind))return c.get();worker.run(c.get());}throw new AssertionError();}
 String job(Fixture f,String column,String kind){return db.queryForObject("SELECT "+column+" FROM stock_recovery_job WHERE intent_id=? AND kind=?",String.class,f.intent().id(),kind);}
 void due(Fixture f)throws Exception{while(db.queryForObject("SELECT clock_timestamp()<deadline_at FROM stock_hold_intent WHERE id=?",Boolean.class,f.intent().id()))Thread.sleep(20);}
 void leaseEnded(StockRecoveryStore.Claim c)throws Exception{while(db.queryForObject("SELECT lease_until>clock_timestamp() FROM stock_recovery_job WHERE intent_id=? AND kind=?",Boolean.class,c.intentId(),c.kind()))Thread.sleep(20);}
 @Test void intentAndExpiryJobAreAtomicAndHaveOriginalDeadline(){var f=fixture();assertEquals("WAITING",job(f,"state","UNUSED"));assertEquals(f.intent().deadlineAt(),db.queryForObject("SELECT next_attempt_at FROM stock_recovery_job WHERE intent_id=? AND kind='UNUSED'",OffsetDateTime.class,f.intent().id()));assertEquals("0",job(f,"attempts::text","UNUSED"));}
 @Test void enqueueFailureRollsBackNewIntentAndProgress(){var f=fixture();db.execute("ALTER TABLE stock_recovery_job ADD CONSTRAINT recovery_seed_fault CHECK(intent_id='"+f.intent().id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->holds.prepare(f.owner(),new Place(UUID.randomUUID(),f.ticket(),1,1,1200)));assertEquals(1,db.queryForObject("SELECT count(*) FROM stock_hold_intent WHERE customer_id=?",Integer.class,f.owner().id()));}finally{db.execute("ALTER TABLE stock_recovery_job DROP CONSTRAINT recovery_seed_fault");}}
 @Test void decisionJobFailureRollsBackFormalOrderAndResult(){var f=fixture();var p=accept(f);db.execute("ALTER TABLE stock_recovery_job ADD CONSTRAINT recovery_result_fault CHECK(kind<>'SETTLEMENT' OR intent_id<>'"+f.intent().id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->purchases.process(event(p)));assertEquals("PROCESSING",purchases.detail(f.owner(),p.id()).status());assertEquals(0,held(f));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_decision WHERE intent_id=?",Integer.class,f.intent().id()));}finally{db.execute("ALTER TABLE stock_recovery_job DROP CONSTRAINT recovery_result_fault");}purchases.process(event(p));assertEquals("WAITING",job(f,"state","SETTLEMENT"));}
 @Test void recoveryFlagOffDoesNotClaimOrAcknowledge(){var f=fixture();reserve(f);worker.sweep();assertEquals("0",job(f,"attempts::text","SETTLEMENT"));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_ack WHERE intent_id=?",Integer.class,f.intent().id()));}
 @Test void actualScheduledWorkerMethodCompletesCommitWhenEnabled(){drain();var f=fixture();reserve(f);new StockRecoveryWorker(recovery,holds,settlement,true,30,10).sweep();assertEquals("DONE",job(f,"state","SETTLEMENT"));assertEquals("COMMITTED",job(f,"last_code","SETTLEMENT"));assertEquals(Status.COMMITTED,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(1,held(f));}
 @Test void cancelledAcceptedJobReleasesFromFormalDecision(){var f=fixture();var p=accept(f);purchases.cancel(f.owner(),p.id(),new Cancel(UUID.randomUUID(),1));var c=claim(f,"SETTLEMENT");assertTrue(worker.run(c));assertEquals("DONE",job(f,"state","SETTLEMENT"));assertEquals("RELEASED",job(f,"last_code","SETTLEMENT"));assertEquals(4,ledger.snapshot(f.ticket(),1).snapshot().available());}
 @Test void dueUnusedHeldHasCommittedAbandonmentBeforeRelease()throws Exception{var f=fixture(2);due(f);var c=claim(f,"UNUSED");assertTrue(worker.run(c));assertEquals("ABORTED",holds.inspect(f.intent().id()).state());assertEquals("DONE",job(f,"state","UNUSED"));assertEquals(Status.RELEASED,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(0,held(f));}
 @Test void duePreparedReceiptAbsenceIsRecordedWithoutInventingHold()throws Exception{var f=fixture(2);var i=holds.prepare(f.owner(),new Place(UUID.randomUUID(),f.ticket(),1,1,1200));var other=new Fixture(f.owner(),f.ticket(),f.body(),i);due(other);var c=claim(other,"UNUSED");assertTrue(worker.run(c));assertEquals("ABSENT",db.queryForObject("SELECT resolution FROM stock_hold_progress WHERE intent_id=?",String.class,i.id()));}
 @Test void acceptedProcessingExpiryJobNeverRawReleasesReceipt()throws Exception{var f=fixture(2);var p=accept(f);due(f);var c=claim(f,"UNUSED");assertTrue(worker.run(c));assertEquals("ACCEPTED",job(f,"last_code","UNUSED"));assertEquals("PROCESSING",purchases.detail(f.owner(),p.id()).status());assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals("HELD",holds.inspect(f.intent().id()).state());assertTrue(purchases.expire(p.id()));assertTrue(worker.run(claim(f,"SETTLEMENT")));assertEquals(Status.RELEASED,ledger.lookup(f.ticket(),claim(f)).receipt().status());}
 @Test void staleEarlyExpiryObservationRechecksDeadlineBeforeDecision(){var f=fixture();assertEquals("NOT_DUE",holds.recoverUnused(f.intent().id(),()->{}).failure());assertEquals("HELD",holds.inspect(f.intent().id()).state());assertEquals("READY",projections.inspect(f.ticket()).state());assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());}
 @Test void acceptanceWinningRaceCannotBeAbandonedByStaleRecoveryObservation()throws Exception{var f=fixture(3);var p=accept(f);try(var pool=Executors.newFixedThreadPool(2)){for(var r:pool.invokeAll(List.<Callable<String>>of(()->{due(f);return holds.recoverUnused(f.intent().id(),()->{}).failure();},()->purchases.acceptHold(f.owner(),f.intent().id()).status())))assertTrue(Set.of("ACCEPTED","PROCESSING").contains(r.get()));}assertEquals("HELD",holds.inspect(f.intent().id()).state());assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(p.id(),accept(f).id());}
 @Test void sixConcurrentClaimsHaveOneLeaseAndOneAttempt()throws Exception{drain();var f=fixture();reserve(f);try(var pool=Executors.newFixedThreadPool(6)){var tasks=new ArrayList<Callable<Optional<StockRecoveryStore.Claim>>>();for(int n=0;n<6;n++)tasks.add(()->recovery.claim(30));var owned=new ArrayList<StockRecoveryStore.Claim>();for(var r:pool.invokeAll(tasks))if(r.get().isPresent()){var c=r.get().get();if(c.intentId().equals(f.intent().id()))owned.add(c);else worker.run(c);}assertEquals(1,owned.size());assertEquals(1,owned.getFirst().attempt());assertTrue(worker.run(owned.getFirst()));}assertEquals("DONE",job(f,"state","SETTLEMENT"));}
 @Test void expiredLeaseIsReclaimedAndOldWorkerCannotWriteOrFinish()throws Exception{drain();var f=fixture();reserve(f);var first=claim(f,"SETTLEMENT",1);leaseEnded(first);var next=claim(f,"SETTLEMENT");assertEquals(2,next.attempt());assertNotEquals(first.token(),next.token());assertFalse(worker.run(first));assertFalse(recovery.failed(first,"REDIS_UNKNOWN",false));assertFalse(recovery.complete(first,"COMMITTED"));assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertTrue(worker.run(next));assertFalse(worker.run(first));assertEquals("DONE",job(f,"state","SETTLEMENT"));}
 @Test void sixCrashesConsumeBudgetAndExpiredFinalLeaseNeedsReview()throws Exception{drain();var f=fixture();reserve(f);for(int n=1;n<=6;n++){var c=claim(f,"SETTLEMENT",1);assertEquals(n,c.attempt());leaseEnded(c);}var next=recovery.claim(30);next.ifPresent(worker::run);assertEquals("REVIEW",job(f,"state","SETTLEMENT"));assertEquals("LEASE_EXHAUSTED",job(f,"last_code","SETTLEMENT"));assertEquals(6,db.queryForObject("SELECT count(*) FROM stock_recovery_claim WHERE intent_id=? AND kind='SETTLEMENT'",Integer.class,f.intent().id()));assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());}
 @Test void ackPgFailureRetainsRedisTerminalAndRetryRecoversOriginalReceipt()throws Exception{var f=fixture();reserve(f);var c=claim(f,"SETTLEMENT");db.execute("ALTER TABLE stock_hold_ack ADD CONSTRAINT recovery_ack_fault CHECK(intent_id<>'"+f.intent().id()+"'::uuid) NOT VALID");try{assertTrue(worker.run(c));assertEquals("WAITING",job(f,"state","SETTLEMENT"));assertEquals("PG_FAILURE",job(f,"last_code","SETTLEMENT"));assertEquals(Status.COMMITTED,ledger.lookup(f.ticket(),claim(f)).receipt().status());}finally{db.execute("ALTER TABLE stock_hold_ack DROP CONSTRAINT recovery_ack_fault");}Thread.sleep(1100);assertTrue(worker.run(claim(f,"SETTLEMENT")));assertEquals("DONE",job(f,"state","SETTLEMENT"));assertEquals(1,ledger.snapshot(f.ticket(),1).snapshot().committed());assertEquals(3,ledger.snapshot(f.ticket(),1).snapshot().available());}
 @Test void lostLeaseAfterLuaRollsBackAckAndReplaysSameTerminal(){var f=fixture();reserve(f);var calls=new java.util.concurrent.atomic.AtomicInteger();assertThrows(StockRecoveryStore.LostLease.class,()->settlement.reconcile(f.intent().id(),()->{if(calls.incrementAndGet()==4)throw new StockRecoveryStore.LostLease();}));assertEquals(Status.COMMITTED,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_ack WHERE intent_id=?",Integer.class,f.intent().id()));assertEquals("DIRTY",projections.inspect(f.ticket()).state());assertTrue(worker.run(claim(f,"SETTLEMENT")));assertEquals(1,ledger.snapshot(f.ticket(),1).snapshot().committed());}
 @Test void corruptionMovesDirectlyToReviewAndDoesNotRepairLedger(){var f=fixture();reserve(f);redis.delete(ledger.key(f.ticket(),1));redis.opsForValue().set(ledger.key(f.ticket(),1),"synthetic wrong type");assertTrue(worker.run(claim(f,"SETTLEMENT")));assertEquals("REVIEW",job(f,"state","SETTLEMENT"));assertEquals("REDIS_CORRUPT",job(f,"last_code","SETTLEMENT"));assertEquals("synthetic wrong type",redis.opsForValue().get(ledger.key(f.ticket(),1)));active(f);}
 @Test void oppositeReceiptStaysOppositeAndRequiresReview(){var f=fixture();reserve(f);ledger.release(f.ticket(),claim(f));assertTrue(worker.run(claim(f,"SETTLEMENT")));assertEquals("REVIEW",job(f,"state","SETTLEMENT"));assertEquals("REDIS_DECISION_CONFLICT",job(f,"last_code","SETTLEMENT"));assertEquals(Status.RELEASED,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(1,held(f));active(f);}
 @Test void missingEpochIsEvidenceAndNeverReseeded(){var f=fixture();reserve(f);redis.delete(ledger.key(f.ticket(),1));assertTrue(worker.run(claim(f,"SETTLEMENT")));assertEquals("KEY_MISSING",job(f,"last_code","SETTLEMENT"));assertFalse(redis.hasKey(ledger.key(f.ticket(),1)));ready(f.ticket());assertEquals(3,ledger.snapshot(f.ticket(),2).snapshot().available());}
 @Test void jobCompletionLossAfterAckNeedsOnlyIdempotentReceiptUpdate()throws Exception{drain();var f=fixture();reserve(f);var c=claim(f,"SETTLEMENT",1);settlement.reconcile(f.intent().id(),()->recovery.fence(c));leaseEnded(c);assertFalse(recovery.complete(c,"COMMITTED"));var next=claim(f,"SETTLEMENT");assertTrue(worker.run(next));assertEquals(1,ledger.snapshot(f.ticket(),1).snapshot().committed());assertEquals("DONE",job(f,"state","SETTLEMENT"));}
 @Test void sqlGuardsProtectJobIdentityBudgetClaimAuditAndDoneEvidence(){var f=fixture();reserve(f);var c=claim(f,"SETTLEMENT");assertThrows(org.springframework.dao.DataAccessException.class,()->recovery.complete(c,"COMMITTED"));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_recovery_job SET max_attempts=20 WHERE intent_id=?",f.intent().id()));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("DELETE FROM stock_recovery_job WHERE intent_id=?",f.intent().id()));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_recovery_claim SET token=token WHERE intent_id=?",f.intent().id()));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("DELETE FROM stock_recovery_claim WHERE intent_id=?",f.intent().id()));assertTrue(worker.run(c));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_recovery_job SET last_code=last_code WHERE intent_id=? AND kind='SETTLEMENT'",f.intent().id()));}
 @Test void unsafeCodesAndOuterTransactionAreRefused(){var f=fixture();reserve(f);var c=claim(f,"SETTLEMENT");assertThrows(IllegalArgumentException.class,()->recovery.failed(c,"raw secret or exception text",false));new TransactionTemplate(transactions).execute(tx->{assertThrows(IllegalStateException.class,()->worker.run(c));return null;});assertThrows(IllegalStateException.class,()->recovery.fence(c));assertTrue(worker.run(c));}
 @Test void persistedAbandonmentIsClaimableBeforeOriginalDeadlineWithoutSkippingRetryDelay(){var f=fixture();redis.delete(ledger.key(f.ticket(),1));redis.opsForValue().set(ledger.key(f.ticket(),1),"synthetic wrong type");assertEquals("ABORTING",holds.abandon(f.intent().id()).state());assertTrue(db.queryForObject("SELECT clock_timestamp()<deadline_at FROM stock_hold_intent WHERE id=?",Boolean.class,f.intent().id()));redis.delete(ledger.key(f.ticket(),1));var c=claim(f,"UNUSED");assertTrue(worker.run(c));assertEquals("ABORTED",holds.inspect(f.intent().id()).state());assertEquals("KEY_MISSING",db.queryForObject("SELECT resolution FROM stock_hold_progress WHERE intent_id=?",String.class,f.intent().id()));}

}
